// ═══════════════════════════════════════════
// Extract & Validate Domain from Telegram message
// ═══════════════════════════════════════════

const message = $input.item.json.message?.text || '';
let input = message.trim();

// Remove bot command prefix if present
if (input.startsWith('/lead')) {
  input = input.replace(/^\/lead\s*/, '').trim();
}
if (input.startsWith('/start')) {
  return {
    json: {
      error: true,
      chatId: $input.item.json.message.chat.id,
      errorMessage: '👋 Привіт! Відправ мені домен компанії (наприклад: example.com) і я згенерую персоналізований cold email для неї.'
    }
  };
}

let domain = input;

// Remove protocol
domain = domain.replace(/^(https?:\/\/)?(www\.)?/i, '');
// Remove path, query, fragment
domain = domain.split('/')[0].split('?')[0].split('#')[0];
// Remove trailing dots
domain = domain.replace(/\.+$/, '');

// Basic validation
if (!domain || !domain.includes('.') || domain.length < 4) {
  return {
    json: {
      error: true,
      chatId: $input.item.json.message.chat.id,
      errorMessage: `❌ Невалідний домен: "${message}"\n\n📝 Відправ домен у форматі: example.com`
    }
  };
}

const chatId = $input.item.json.message.chat.id;

return {
  json: {
    error: false,
    domain: domain.toLowerCase(),
    url: `https://${domain.toLowerCase()}`,
    chatId: chatId,
    timestamp: new Date().toISOString()
  }
};

// ═══════════════════════════════════════════
// Prepare LLM Input: clean scraped data + build prompt
// ═══════════════════════════════════════════

const firecrawlResponse = $input.item.json;
const extractDomain = $('Extract Domain').first().json;
const domain = extractDomain.domain;
const chatId = extractDomain.chatId;

// Extract markdown content from Firecrawl response
let content = '';

if (firecrawlResponse.data && firecrawlResponse.data.markdown) {
  content = firecrawlResponse.data.markdown;
} else if (firecrawlResponse.data && firecrawlResponse.data.content) {
  content = firecrawlResponse.data.content;
} else if (typeof firecrawlResponse.data === 'string') {
  content = firecrawlResponse.data;
} else {
  content = JSON.stringify(firecrawlResponse.data || firecrawlResponse, null, 2);
}

// Clean up the content
content = content
  // Remove excessive whitespace
  .replace(/\n{4,}/g, '\n\n\n')
  // Remove image markdown that adds noise
  .replace(/!\[.*?\]\(.*?\)/g, '')
  // Remove very long URLs
  .replace(/https?:\/\/[^\s]{200,}/g, '[long-url-removed]')
  .trim();

// Truncate to avoid token limits (~6000 chars ≈ ~1500 tokens)
const MAX_CHARS = 6000;
if (content.length > MAX_CHARS) {
  content = content.substring(0, MAX_CHARS) + '\n\n[...content truncated for token efficiency...]';
}

// Check if we got meaningful content
if (content.length < 50) {
  content = `Could not extract meaningful content from ${domain}. The website may be JavaScript-heavy or blocking scraping. Please analyze based on the domain name alone: ${domain}`;
}

// Build the system prompt
const systemPrompt = `You are an elite B2B Sales Development Representative (SDR) specializing in the Real Estate industry. You help real estate agencies, property management companies, and construction firms leverage AI-powered automation to grow their business.

TASK: Analyze the following website content and produce a structured analysis + hyper-personalized cold email.

=== ANALYSIS INSTRUCTIONS ===
1. COMPANY NAME: Extract the official company name from the website content.
2. INDUSTRY: Categorize precisely (e.g., "Residential Real Estate Agency", "Commercial Property Management", "Construction & Development").
3. MAIN SERVICE: Identify their primary offering.
4. PAIN POINT: Based on what you see, infer their biggest operational pain. Common ones:
   - Slow response time to incoming leads
   - Manual listing creation and updates
   - No systematic follow-up with past clients
   - Time wasted on repetitive client questions
   - Manual data entry from inquiries
5. CONTACT EMAIL: Extract any email address found on the page.

=== COLD EMAIL INSTRUCTIONS ===
Write a SHORT cold email (max 150 words) with this EXACT structure:
1. HOOK (1 sentence): A specific, genuine observation about their website or business.
2. PAIN POINT (1-2 sentences): Address the specific challenge. Use "I noticed..." or "Most agencies like yours spend X hours on...".
3. VALUE PROPOSITION (2-3 sentences): How AI automation solves their problem. Include a specific metric.
4. CTA (1 sentence): Casual ask for a 10-minute call or offer a demo video.

=== STRICT RULES ===
- NEVER start with "I hope this email finds you well"
- Start directly with company name or specific observation
- Conversational tone, not corporate
- ONE pain point only
- At least ONE specific number/metric in value prop
- Write email in English
- Subject line under 50 characters, curiosity-driven

=== OUTPUT FORMAT ===
Respond in valid JSON:
{
  "company_name": "...",
  "industry": "...",
  "main_service": "...",
  "pain_point": "...",
  "contact_email": "... or Not found",
  "cold_email_subject": "...",
  "cold_email_body": "..."
}`;

const userMessage = `Domain: ${domain}\nURL: https://${domain}\n\n=== WEBSITE CONTENT ===\n${content}`;

// Build the OpenAI request body
const requestBody = {
  model: 'gpt-4o',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userMessage }
  ],
  temperature: 0.7,
  max_tokens: 1500,
  response_format: { type: 'json_object' }
};

return {
  json: {
    chatId,
    domain,
    contentLength: content.length,
    requestBody: JSON.stringify(requestBody)
  }
};

// ═══════════════════════════════════════════
// Parse OpenAI response & format for output
// ═══════════════════════════════════════════

const response = $input.item.json;
const prevData = $('Prepare LLM Input').first().json;
const chatId = prevData.chatId;
const domain = prevData.domain;

let aiData;

try {
  const aiContent = response.choices[0].message.content;
  aiData = JSON.parse(aiContent);
} catch (e) {
  // If JSON parsing fails, try to extract what we can
  aiData = {
    company_name: domain,
    industry: 'Unknown',
    main_service: 'Unknown',
    pain_point: 'Could not analyze',
    contact_email: 'Not found',
    cold_email_subject: 'Error parsing AI response',
    cold_email_body: `Raw response: ${response.choices?.[0]?.message?.content || 'No content'}`
  };
}

// Calculate tokens used (for cost tracking)
const tokensUsed = response.usage?.total_tokens || 0;
const estimatedCost = (tokensUsed / 1000000 * 5).toFixed(4); // GPT-4o pricing approx

// Format the data for Google Sheets (matching column headers)
return {
  json: {
    chatId,
    domain,
    // Fields matching Google Sheets columns
    'Дата': new Date().toLocaleString('uk-UA', { timeZone: 'Europe/Kyiv' }),
    'Компанія': aiData.company_name || domain,
    'Домен': domain,
    'Сфера': aiData.industry || 'N/A',
    'Сервіс': aiData.main_service || 'N/A',
    'Біль': aiData.pain_point || 'N/A',
    'Email': aiData.contact_email || 'Not found',
    'Тема': aiData.cold_email_subject || 'N/A',
    'Лист': aiData.cold_email_body || 'N/A',
    // Metadata (not written to sheets)
    _tokensUsed: tokensUsed,
    _estimatedCost: `$${estimatedCost}`,
    _emailSubject: aiData.cold_email_subject,
    _emailBody: aiData.cold_email_body,
    _painPoint: aiData.pain_point
  }
};
